.step { display: block; margin-top: 22px; color: #94a3b8; font-size: 0.9rem; }
.step input {
  width: 64px;
  margin-left: 8px;
  padding: 6px;
  background: #111a2e;
  border: 1px solid #334155;
  color: #f8fafc;
  border-radius: 4px;
}

// Get the elements we need
const countEl = document.getElementById("count");
const stepEl = document.getElementById("step");

let count = 0;

// Show the number and colour it by sign
function render() {
  countEl.textContent = count;
  countEl.classList.toggle("positive", count > 0);
  countEl.classList.toggle("negative", count < 0);
}

function getStep() {
  const step = Number(stepEl.value);
  return step > 0 ? step : 1;
}

document.getElementById("plus").addEventListener("click", () => {
  count += getStep();
  render();
});

document.getElementById("minus").addEventListener("click", () => {
  count -= getStep();
  render();
});

document.getElementById("reset").addEventListener("click", () => {
  count = 0;
  render();
});

render();

const $ = (id) => document.getElementById(id);

// 1. Variables: const, let and different types
$("varsBtn").addEventListener("click", () => {
  const name = "Muhammadmuso";   // string
  let year = 2026;               // number
  const isStudent = true;        // boolean
  const skills = ["HTML", "CSS", "JS"]; // array
  year = year + 1;               // let can change
  $("varsOut").textContent =
    `name: ${name} (${typeof name})\n` +
    `next year: ${year} (${typeof year})\n` +
    `isStudent: ${isStudent} (${typeof isStudent})\n` +
    `skills: ${skills.join(", ")} (${skills.length} items)`;
});

// 2. Change an element with the DOM
$("changeBtn").addEventListener("click", () => {
  const p = $("target");
  p.textContent = "I was changed by JavaScript!";
  p.style.color = "#16a34a";
  p.style.fontWeight = "bold";
});

// 3. Read user input
$("greetBtn").addEventListener("click", () => {
  const name = $("nameInput").value.trim();
  $("greetOut").textContent = name ? `Hello, ${name}! 👋` : "Please type your name first.";
});

// 4. Conditions: if / else if / else
$("scoreBtn").addEventListener("click", () => {
  const score = Number($("scoreInput").value);
  let message;
  if ($("scoreInput").value === "" || score < 0 || score > 100) message = "Enter a score from 0 to 100.";
  else if (score >= 90) message = "A - Excellent!";
  else if (score >= 80) message = "B - Good job.";
  else if (score >= 70) message = "C - Not bad.";
  else if (score >= 60) message = "D - You passed.";
  else message = "F - Keep practising.";
  $("scoreOut").textContent = message;
});

// 5. Loops: build a times table
$("loopBtn").addEventListener("click", () => {
  const n = Number($("loopInput").value) || 1;
  let lines = "";
  for (let i = 1; i <= 9; i++) {
    lines += `${n} x ${i} = ${n * i}\n`;
  }
  $("loopOut").textContent = lines;
});

// 6. localStorage: the note survives a page reload
function showNote() {
  let saved = null;
  try { saved = localStorage.getItem("labNote"); } catch (e) {}
  $("noteOut").textContent = saved ? `Saved note: ${saved}` : "No note saved yet.";
}
$("saveBtn").addEventListener("click", () => {
  const text = $("noteInput").value.trim();
  if (!text) return;
  try { localStorage.setItem("labNote", text); } catch (e) {}
  $("noteInput").value = "";
  showNote();
});
$("clearBtn").addEventListener("click", () => {
  try { localStorage.removeItem("labNote"); } catch (e) {}
  showNote();
});
showNote();

