const form = document.getElementById("searchForm");
const queryInput = document.getElementById("query");
const statusEl = document.getElementById("status");
const resultsEl = document.getElementById("results");

function setStatus(text, isError = false) {
  statusEl.textContent = text;
  statusEl.classList.toggle("error", isError);
}

function bookCard(book) {
  const card = document.createElement("article");
  card.className = "book";

  const link = document.createElement("a");
  link.href = `https://openlibrary.org${book.key}`;
  link.target = "_blank";
  link.rel = "noopener noreferrer";

  if (book.cover_i) {
    const img = document.createElement("img");
    img.src = `https://covers.openlibrary.org/b/id/${book.cover_i}-M.jpg`;
    img.alt = `Cover of ${book.title}`;
    img.loading = "lazy";
    link.appendChild(img);
  } else {
    const noCover = document.createElement("div");
    noCover.className = "no-cover";
    noCover.textContent = "No cover";
    link.appendChild(noCover);
  }

  const info = document.createElement("div");
  info.className = "info";
  const title = document.createElement("h3");
  title.textContent = book.title;
  const author = document.createElement("p");
  author.textContent = book.author_name ? book.author_name.slice(0, 2).join(", ") : "Unknown author";
  const year = document.createElement("p");
  year.textContent = book.first_publish_year ? `since ${book.first_publish_year}` : "";
  info.append(title, author, year);
  link.appendChild(info);

  card.appendChild(link);
  return card;
}

async function searchBooks(query) {
  setStatus("Searching...");
  resultsEl.innerHTML = "";
  try {
    const url = `https://openlibrary.org/search.json?q=${encodeURIComponent(query)}&limit=24`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`Request failed (${res.status})`);
    const data = await res.json();

    if (data.docs.length === 0) {
      setStatus(`No books found for "${query}".`);
      return;
    }
    setStatus(`Found ${data.numFound.toLocaleString()} books. Showing ${data.docs.length}.`);
    data.docs.forEach((book) => resultsEl.appendChild(bookCard(book)));
  } catch (err) {
    setStatus(err instanceof TypeError ? "Network error. Check your connection." : err.message, true);
  }
}

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const query = queryInput.value.trim();
  if (query) searchBooks(query);
});

