import { useState } from "react";

const PRODUCTS = [
  { id: 1, name: "Mechanical Keyboard", price: 89000, icon: "⌨️" },
  { id: 2, name: "Wireless Mouse", price: 32000, icon: "🖱️" },
  { id: 3, name: "USB-C Hub", price: 45000, icon: "🔌" },
  { id: 4, name: "Laptop Stand", price: 39000, icon: "💻" },
  { id: 5, name: "Noise-cancelling Headphones", price: 159000, icon: "🎧" },
  { id: 6, name: "Desk Lamp", price: 27000, icon: "💡" },
];

const won = (n) => n.toLocaleString("ko-KR") + " ₩";

export default function App() {
  // cart: [{ id, name, price, icon, qty }]
  const [cart, setCart] = useState([]);

  function addToCart(product) {
    setCart((prev) => {
      const found = prev.find((item) => item.id === product.id);
      if (found) {
        return prev.map((item) =>
          item.id === product.id ? { ...item, qty: item.qty + 1 } : item
        );
      }
      return [...prev, { ...product, qty: 1 }];
    });
  }

  function changeQty(id, amount) {
    setCart((prev) =>
      prev
        .map((item) => (item.id === id ? { ...item, qty: item.qty + amount } : item))
        .filter((item) => item.qty > 0)
    );
  }

  function removeItem(id) {
    setCart((prev) => prev.filter((item) => item.id !== id));
  }

  // Derived values: computed from state, not stored in state
  const count = cart.reduce((sum, item) => sum + item.qty, 0);
  const total = cart.reduce((sum, item) => sum + item.qty * item.price, 0);

  return (
    <div className="shop">
      <header className="top">
        <h1>muso<span>.shop</span></h1>
        <span className="badge">🛒 {count}</span>
      </header>

      <div className="layout">
        <section>
          <h2>Desk setup</h2>
          <ul className="products">
            {PRODUCTS.map((p) => {
              const inCart = cart.find((item) => item.id === p.id);
              return (
                <li key={p.id} className="product">
                  <span className="icon">{p.icon}</span>
                  <div className="info">
                    <strong>{p.name}</strong>
                    <span className="muted">{won(p.price)}</span>
                  </div>
                  <button className="btn" onClick={() => addToCart(p)}>
                    {inCart ? `Add another (${inCart.qty})` : "Add"}
                  </button>
                </li>
              );
            })}
          </ul>
        </section>

        <aside className="cart">
          <h2>Your cart</h2>
          {cart.length === 0 ? (
            <p className="muted">Nothing here yet.</p>
          ) : (
            <>
              <ul>
                {cart.map((item) => (
                  <li key={item.id} className="line">
                    <span>{item.icon} {item.name}</span>
                    <div className="qty">
                      <button onClick={() => changeQty(item.id, -1)}>−</button>
                      <span>{item.qty}</span>
                      <button onClick={() => changeQty(item.id, 1)}>+</button>
                      <button className="remove" onClick={() => removeItem(item.id)}>✕</button>
                    </div>
                  </li>
                ))}
              </ul>
              <p className="total">Total <strong>{won(total)}</strong></p>
              <button className="btn wide" onClick={() => setCart([])}>Checkout</button>
            </>
          )}
        </aside>
      </div>
    </div>
  );
}

