import { useState, useEffect } from "react";

// 1. Run once: empty dependency array
function RunOnce() {
  const [log, setLog] = useState([]);
  useEffect(() => {
    setLog((l) => [...l, "Mounted at " + new Date().toLocaleTimeString()]);
  }, []);
  return <p className="out">{log.join("\n")}</p>;
}

// 2. Run when a value changes
function RunOnChange() {
  const [count, setCount] = useState(0);
  const [message, setMessage] = useState("");
  useEffect(() => {
    setMessage(count % 2 === 0 ? `${count} is even` : `${count} is odd`);
  }, [count]);
  return (
    <div className="row">
      <button className="btn" onClick={() => setCount(count + 1)}>count: {count}</button>
      <span className="out inline">{message}</span>
    </div>
  );
}

// 3. Clean up: stop the interval when the clock is hidden
function LiveClock() {
  const [time, setTime] = useState(new Date());
  useEffect(() => {
    const id = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(id); // cleanup
  }, []);
  return <p className="clock">{time.toLocaleTimeString()}</p>;
}

function ClockToggle() {
  const [show, setShow] = useState(true);
  return (
    <div>
      <button className="btn" onClick={() => setShow(!show)}>{show ? "Hide" : "Show"} clock</button>
      {show && <LiveClock />}
    </div>
  );
}

// 4. Sync with localStorage
function ThemeSync() {
  const [dark, setDark] = useState(() => {
    try { return localStorage.getItem("w12-theme") !== "light"; } catch (e) { return true; }
  });
  useEffect(() => {
    try { localStorage.setItem("w12-theme", dark ? "dark" : "light"); } catch (e) {}
  }, [dark]);
  return (
    <div className={dark ? "theme dark" : "theme light"}>
      <span>{dark ? "🌙 Dark" : "☀️ Light"} (remembered after reload)</span>
      <button className="btn" onClick={() => setDark(!dark)}>Switch</button>
    </div>
  );
}

// 5. Sync the document title
function DocumentTitle() {
  const [unread, setUnread] = useState(0);
  useEffect(() => {
    document.title = unread > 0 ? `(${unread}) new messages` : "No new messages";
  }, [unread]);
  return (
    <div className="row">
      <button className="btn" onClick={() => setUnread(unread + 1)}>New message</button>
      <button className="btn ghost" onClick={() => setUnread(0)}>Mark all read</button>
      <span className="out inline">document.title = "{unread > 0 ? `(${unread}) new messages` : "No new messages"}"</span>
    </div>
  );
}

// 6. Don't store derived values: fullName is computed, no effect needed
function DerivedName() {
  const [first, setFirst] = useState("Muhammad");
  const [last, setLast] = useState("Muso");
  const fullName = `${first} ${last}`.trim();
  return (
    <div className="row">
      <input value={first} onChange={(e) => setFirst(e.target.value)} placeholder="First name" />
      <input value={last} onChange={(e) => setLast(e.target.value)} placeholder="Last name" />
      <span className="out inline">{fullName || "—"}</span>
    </div>
  );
}

const DEMOS = [
  ["Run once", "useEffect(fn, [])", RunOnce],
  ["Run on change", "useEffect(fn, [count])", RunOnChange],
  ["Clean up", "return () => clearInterval(id)", ClockToggle],
  ["Sync storage", "localStorage.setItem(...)", ThemeSync],
  ["Sync the title", "document.title = ...", DocumentTitle],
  ["Derived value", "no effect needed", DerivedName],
];

export default function App() {
  return (
    <main className="page">
      <h1>useEffect<span>()</span></h1>
      <p className="muted">Six small demos of when an effect runs, and when you don't need one.</p>
      {DEMOS.map(([title, code, Demo], i) => (
        <section key={title} className="demo">
          <div className="label">
            <span className="num">0{i + 1}</span>
            <h2>{title}</h2>
            <code>{code}</code>
          </div>
          <div className="body"><Demo /></div>
        </section>
      ))}
    </main>
  );
}

