  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const controllerRef = useRef(null);

  async function fetchUser(name) {
    const query = name.trim();
    if (!query) { setUser(null); setError(""); return; }

    // BONUS: abort the previous request
    if (controllerRef.current) controllerRef.current.abort();
    const controller = new AbortController();
    controllerRef.current = controller;

    setLoading(true);
    setError("");
    setUser(null);
    try {
      const res = await fetch(`https://api.github.com/users/${encodeURIComponent(query)}`, {
        signal: controller.signal,
      });
      if (res.status === 404) throw new Error("User not found");
      if (!res.ok) throw new Error(`Request failed (${res.status})`);
      setUser(await res.json());
    } catch (err) {
      if (err.name === "AbortError") return;
      setError(err.message);
    } finally {
      if (controllerRef.current === controller) setLoading(false);
    }
  }

  // Debounce: search 500ms after typing stops
  useEffect(() => {
    const timer = setTimeout(() => fetchUser(username), 500);
    return () => clearTimeout(timer);
  }, [username]);

  useEffect(() => () => controllerRef.current?.abort(), []);

  return (
    <main className="lookup">
      <h1><span>$</span> gh user</h1>
      <form onSubmit={(e) => { e.preventDefault(); fetchUser(username); }}>
        <input
          placeholder="username, e.g. muso081"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
        />
        <button className="btn" type="submit">Search</button>
      </form>

      {loading && <p className="muted">fetching…</p>}
      {error && <p className="error">{error}</p>}

      {user && !loading && (
        <article className="profile">
          <img src={user.avatar_url} alt={user.login} />
          <div>
            <h2>{user.name || user.login}</h2>
            <a href={user.html_url} target="_blank" rel="noreferrer">@{user.login}</a>
            <p className="muted">{user.bio || "No bio"}</p>
            <div className="stats">
              <span><b>{user.followers}</b> followers</span>
              <span><b>{user.public_repos}</b> repos</span>
            </div>
          </div>
        </article>
      )}
    </main>
  );
}

