import { useState, useEffect } from "react";

// WMO weather codes used by Open-Meteo
const CODES = {
  0: ["Clear sky", "☀️"], 1: ["Mainly clear", "🌤️"], 2: ["Partly cloudy", "⛅"], 3: ["Overcast", "☁️"],
  45: ["Fog", "🌫️"], 48: ["Rime fog", "🌫️"],
  51: ["Light drizzle", "🌦️"], 53: ["Drizzle", "🌦️"], 55: ["Dense drizzle", "🌧️"],
  56: ["Freezing drizzle", "🌧️"], 57: ["Freezing drizzle", "🌧️"],
  61: ["Slight rain", "🌦️"], 63: ["Rain", "🌧️"], 65: ["Heavy rain", "🌧️"],
  66: ["Freezing rain", "🌧️"], 67: ["Freezing rain", "🌧️"],
  71: ["Slight snow", "🌨️"], 73: ["Snow", "🌨️"], 75: ["Heavy snow", "❄️"], 77: ["Snow grains", "❄️"],
  80: ["Rain showers", "🌦️"], 81: ["Rain showers", "🌧️"], 82: ["Violent showers", "⛈️"],
  85: ["Snow showers", "🌨️"], 86: ["Snow showers", "❄️"],
  95: ["Thunderstorm", "⛈️"], 96: ["Thunderstorm, hail", "⛈️"], 99: ["Thunderstorm, hail", "⛈️"],
};

async function readJson(res) {
  if (res.ok) return res.json();
  if (res.status === 429) throw new Error("Rate limit reached. Wait a minute and try again.");
  let reason = "";
  try { reason = (await res.json()).reason || ""; } catch (e) {}
  if (res.status === 400) throw new Error(`Bad coordinates: ${reason || "check latitude/longitude"}`);
  throw new Error(`Request failed (${res.status}) ${reason}`);
}

const niceError = (err) =>
  err instanceof TypeError ? "Network error. Check your internet connection." : err.message;

export default function App() {
  const [coords, setCoords] = useState({ lat: 37.5665, lon: 126.978, name: "Seoul" });
  const [weather, setWeather] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [city, setCity] = useState("");
  const [lat, setLat] = useState("");
  const [lon, setLon] = useState("");

  // useEffect fetch: runs whenever the coordinates change
  useEffect(() => {
    const controller = new AbortController();
    setLoading(true);
    setError("");
    fetch(
      `https://api.open-meteo.com/v1/forecast?latitude=${coords.lat}&longitude=${coords.lon}` +
        `&current=temperature_2m,wind_speed_10m,weather_code`,
      { signal: controller.signal }
    )
      .then(readJson)
      .then((data) => {
        setWeather({
          temp: data.current.temperature_2m,
          wind: data.current.wind_speed_10m,
          code: data.current.weather_code,
        });
        setLoading(false);
      })
      .catch((err) => {
        if (err.name === "AbortError") return;
        setWeather(null);
        setError(niceError(err));
        setLoading(false);
      });
    return () => controller.abort();
  }, [coords]);

  // City name -> geocoding endpoint -> coordinates
  async function searchCity(e) {
    e.preventDefault();
    const name = city.trim();
    if (!name) return;
    setLoading(true);
    setError("");
    try {
      const data = await readJson(
        await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(name)}&count=1`)
      );
      if (!data.results?.length) throw new Error(`City "${name}" not found`);
      const p = data.results[0];
      setCoords({ lat: p.latitude, lon: p.longitude, name: p.country ? `${p.name}, ${p.country}` : p.name });
    } catch (err) {
      setWeather(null);
      setError(niceError(err));
      setLoading(false);
    }
  }

  function searchCoords(e) {
    e.preventDefault();
    const la = parseFloat(lat), lo = parseFloat(lon);
    if (isNaN(la) || isNaN(lo) || la < -90 || la > 90 || lo < -180 || lo > 180) {
      setWeather(null);
      setError("Bad coordinates: latitude -90 to 90, longitude -180 to 180.");
      return;
    }
    setCoords({ lat: la, lon: lo, name: `${la.toFixed(2)}, ${lo.toFixed(2)}` });
  }

  // Bonus: navigator.geolocation
  function locateMe() {
    if (!navigator.geolocation) { setError("Geolocation is not supported."); return; }
    setLoading(true);
    setError("");
    navigator.geolocation.getCurrentPosition(
      (pos) => setCoords({ lat: pos.coords.latitude, lon: pos.coords.longitude, name: "My location" }),
      () => { setLoading(false); setError("Could not get your location."); }
    );
  }

  const [desc, icon] = weather ? CODES[weather.code] || ["Unknown", "❔"] : ["", ""];

  return (
    <main className="weather">
      <section className="display">
        {loading && <p className="muted">loading…</p>}
        {!loading && error && <p className="error">{error}</p>}
        {!loading && !error && weather && (
          <>
            <p className="place">📍 {coords.name}</p>
            <div className="now">
              <span className="icon">{icon}</span>
              <span className="temp">{weather.temp}<small>°C</small></span>
            </div>
            <p className="desc">{desc}</p>
            <p className="wind">wind {weather.wind} km/h</p>
          </>
        )}
      </section>

      <section className="controls">
        <form onSubmit={searchCity}>
          <label>city</label>
          <div className="row">
            <input placeholder="Busan" value={city} onChange={(e) => setCity(e.target.value)} />
            <button className="btn" disabled={loading}>Go</button>
          </div>
        </form>
        <form onSubmit={searchCoords}>
          <label>lat / lon</label>
          <div className="row">
            <input placeholder="35.18" value={lat} onChange={(e) => setLat(e.target.value)} />
            <input placeholder="129.07" value={lon} onChange={(e) => setLon(e.target.value)} />
            <button className="btn" disabled={loading}>Go</button>
          </div>
        </form>
        <button className="locate" onClick={locateMe} disabled={loading}>⌖ use my location</button>
      </section>
    </main>
  );
}

